/// <summary>
/// Updates the status of AVADelegateToAgent for current record
/// </summary>
/// <param name = "_status">NoYes</param>
public void avaUpdateDelegation(NoYes _status)
{
    this.selectForUpdate(true);

    ttsbegin;
    if (this.isInterCompanyOrder())
    {
        this.AVADelegatedToAgentIC = _status;
    }
    else
    {
        this.AVADelegatedToAgent = _status;
    }
    this.update();
    ttscommit;
}

/// <summary>
/// AVA/WEN/2024/10/31         AVA_012663_HVICOrder
/// </summary>
/// <returns>boolean</returns>
public boolean avaIsCommercialAgentOrigin()
{
    boolean ret = false;
    SalesOrigin salesOrigin = salesOrigin::find(this.SalesOriginId);

    if (salesOrigin.AVACommercialAgentOrig)
    {
        if (this.custTable_CustAccount().interCompanyTradingRelationActive())
        {
            ret = true;
            Error("@NDX:NXAIsCommAgentOrig");
        }
    }
    return ret;
}

/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    SalesTable  salesTableOrig;
    next modifiedField(_fieldId);

    switch(_fieldId)
    {
        case fieldNum(SalesTable, AVAJournalApproval):
            salesTableOrig = this.orig();
            if (this.AVAJournalApproval && !this.InventSiteId)
            {
                this.AVAJournalApproval = salesTableOrig.AVAJournalApproval;
                Error("@NDX:NXASOHeaderSite");
                break;
            }
            if(this.SalesType == SalesType::Journal
                && salesTableOrig.AVAJournalApproval == NoYes::No
                && this.AVAJournalApproval == NoYes::Yes)
            {
                SalesTableType avaSalesTableType = this.type();
                if(!avaSalesTableType.AVAJournalApprovalChangeCheck())
                {
                    this.AVAJournalApproval = NoYes::No;
                }
            }
            break;

        case Fieldnum(SalesTable, SalesType):
            salesTableOrig = this.orig();
            if (    salesTableOrig.SalesType    == SalesType::Journal 
                &&  this.SalesType              == SalesType::Sales)
            {
                if (!this.InventSiteId)
                {
                    this.SalesType = salesTableOrig.SalesType;
                    Error("@NDX:NXASOHeaderSite");
                    break;
                }

                SalesTableType salesTableType = this.type();
                if (salesTableType.AVAcanTypeBeChanged())
                {
                    SalesTable::AVAreorgLineNum(this.SalesId);
                    AVASalesTableOrigQuotationCheck AVASalesTableOrigQuotationCheck =  AVASalesTableOrigQuotationCheck::newFromSalesTable(this);
                    AVASalesTableOrigQuotationCheck.run();
                    if (!this.AVACheckPODublicate()) 
                    {
                        this.PurchOrderFormNum = '';
                    }
                }
                else
                {
                    this.SalesType = SalesType::Journal;
                }

                if (this.custTable_InvoiceAccount().AVACRLCreditBlocked)
                {
                    this.SalesType = SalesType::Journal;
                    error("@NDX:NXACreditLimitBlockedError");
                }
            }
            break;

        case fieldNum(SalesTable, KCS_BOSSpecialPrice):
            this.avaUpdateSpecialPrice();
            break;

        case fieldNum(SalesTable, CustAccount):
            this.avaUpdateCashDiscPayment();
            this.KCS_NoUseQuotPrice = CustTable::find(this.CustAccount).KCS_NoUseQuotPrice;
            break;

        case fieldNum(SalesTable, InvoiceAccount):
            this.avaUpdateCashDiscPayment();
            break;

        case fieldNum(SalesTable, DEL_KCS_CustShipDateReq):
            this.avaUpdateCustShipDateReq();
            break;

        case fieldNum(SalesTable, DlvMode):
            this.AVADlvModeModifiedDateTime             = DateTimeUtil::utcNow();
            this.AVADlvModeModifiedById                 = curUserId();
            this.avaUpdateFreightInformation();
            break;

        case fieldNum(SalesTable, DlvTerm):
            this.AVADlvTermModifiedDateTime             = DateTimeUtil::utcNow();
            this.AVADlvTermModifiedById                 = curUserId();
            this.avaUpdateFreightInformation();
            break;

        case fieldNum(SalesTable, KCS_FreightCosts):
            this.AVAKCS_FreightCostsModifiedDateTime    = DateTimeUtil::utcNow();
            this.AVAKCS_FreightCostsModifiedById        = curUserId();
            break;

        case fieldNum(SalesTable, KCS_ChainId):
            this.initFromSmmBusRelChainGroup();
            break;

        case fieldNum(SalesTable, KCS_PickingReleaseIndicator):
            this.avaUpdateKCS_SOCSalesOrderPickingReleasedBy();
            break;

        case fieldNum(SalesTable, AVADispoDate):
            this.AVADispoDateModifiedDateTime    = DateTimeUtil::utcNow();
            this.AVADispoDateModifiedById        = curUserId();
            //this.avaUpdateDispoDateDemanded();
            break;

        default:
            break;
    }
}

/// <summary>
///    AVA <c>avaUpdateSpecialPrice</c> method.
/// </summary>
public void avaUpdateSpecialPrice()
{
    SalesLine salesLineLoc;

    ttsbegin;
    update_recordset salesLineLoc
    setting AVACBSSpecialPrice = this.KCS_BOSSpecialPrice
    where salesLineLoc.SalesId == this.SalesId;
    ttscommit;
}

/// <summary>
///    AVA <c>avaUpdateCustShipDateReq</c> method.
/// </summary>
public void avaUpdateCustShipDateReq()
{
    SalesLine salesLineLoc;

    ttsbegin;
    update_recordset salesLineLoc
    setting DEL_KCS_CustShipDateReq = this.DEL_KCS_CustShipDateReq
    where salesLineLoc.SalesId == this.SalesId;
    ttscommit;
}

/// <summary>
///    AVA <c>avaUpdateDispoDateDemanded</c> method.
/// </summary>
public void avaUpdateDispoDateDemanded()
{
    SalesLine salesLineLoc;

    ttsbegin;
    update_recordset salesLineLoc
    setting AVADispoDate                    = this.AVADispoDate,
            AVADispoDateModifiedDateTime    = this.AVADispoDateModifiedDateTime,
            AVADispoDateModifiedById        = this.AVADispoDateModifiedById 
    where   salesLineLoc.SalesId        == this.SalesId
        &&  salesLineLoc.SalesStatus    != SalesStatus::Delivered
        &&  salesLineLoc.SalesStatus    != SalesStatus::Invoiced;
    ttscommit;
}

/// <summary>
///    AVA <c>avaDisplaySumPos</c> method.
/// </summary>
/// <returns>
///    <c>Amount</c> as return value
/// </returns>
public display Amount avaDisplaySumPos()
{
    return this.getTotalLineAmount();
}

/// <summary>
///    AVA <c>avaDisplayTotalWeight</c> method.
/// </summary>
/// <returns>
///    <c>Weight</c> as return value
/// </returns>
public display Weight avaDisplayTotalWeight()
{ 
    Weight totalWeightLoc;
    Volume totalVolumeLoc;

    [totalWeightLoc, totalVolumeLoc] = this.totalWeightAndVolume();

    totalWeightLoc = totalWeightLoc / 1000;

    return totalWeightLoc;
}

void insert(boolean _skipMarkup)
{
    Notes   infoTxt1, infoTxt2, infoTxt3, infoTxt4;
    KCS_SOCSalesTableInfoFields infoFields;
    AVADlvResponsible           dlvResp;

    if(this.InterCompanyAutoCreateOrders)
    {
        this.KCS_IC_Reduction = AVASalesParameters::find().KCS_IC_Reduction;

    }

    if (this.SalesType == SalesType::Sales)
    {
        this.KCS_SalesActivation = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
    }

    if (this.InterCompanyOrder)
    {
        if (this.InterCompanyCompanyId && this.InterCompanyCompanyId != curExt())
        {
            changecompany(this.InterCompanyCompanyId)
            {
                dlvResp = SalesTable::find(this.InterCompanyOriginalSalesId).AVADlvResponsible;
            }
            this.AVADlvResponsible = dlvResp;
        }
    }

    next insert(_skipMarkup); 

    if (this.InterCompanyOrder)
    {
        if (this.InterCompanyCompanyId && this.InterCompanyCompanyId != curExt())
        {
            changecompany(this.InterCompanyCompanyId)    
            {
                infoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, this.InterCompanyOriginalSalesId);
                infoTxt1 = infoFields.InfoField1;
                infoTxt2 = infoFields.InfoField2;
                infoTxt3 = infoFields.InfoField3;
                infoTxt4 = infoFields.InfoField4;
            }
            ttsbegin;
            infoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, this.SalesId, true);
            infoFields.InfoField1 = infoTxt1;
            infoFields.InfoField2 = infoTxt2;
            infoFields.InfoField3 = infoTxt3;
            infoFields.InfoField4 = infoTxt4;
            if (infoFields.RecId)
            {
                infoFields.update();
            }
            else
            {
                infoFields.SalesId = this.SalesId;
                infoFields.insert();
            }
            ttscommit;
        }
    }
}

/// <summary>
/// Extension of initFromContactInfo
/// </summary>
void initFromContactInfo()
{
    next initFromContactInfo();

    if(this.custTable_CustAccount().AVAConfirmCentralEmail != '')
    {
        this.Email = this.custTable_CustAccount().AVAConfirmCentralEmail;
    }
}

/// <summary>
///    AVA <c>initFromCustTable</c> method.
/// </summary>
public void initFromCustTable()
{
    next initFromCustTable();

    CustTable custTableLoc;
    smmBusRelChainGroup chainGroupLoc;

    custTableLoc    = this.custTable_CustAccount();
    chainGroupLoc   = smmBusRelChainGroup::avaFindChainId(custTableLoc.CompanyChainId);

    this.KCS_ChainId            = custTableLoc.CompanyChainId;
    this.KCS_CustCity           = custTableLoc.postalAddress().City;
    this.KCS_BOSSpecialPrice    = custTableLoc.KCS_BOSSpecialPrice;
    this.KCS_CentralWarehouse   = custTableLoc.KCS_CentralWarehouse;
    this.KCS_NoUseQuotPrice     = custTableLoc.KCS_NoUseQuotPrice;
    this.AVARicoCustomer        = custTableLoc.AVARicoCustomer;

    this.PriceGroupId           = custTableLoc.PriceGroup           ? custTableLoc.PriceGroup : chainGroupLoc.AVAPriceGroupId;
    this.AVANetPG1              = custTableLoc.AVANetPG1            ? custTableLoc.AVANetPG1 : chainGroupLoc.AVANetPG1;
    this.AVANetPG2              = custTableLoc.AVANetPG2            ? custTableLoc.AVANetPG2 : chainGroupLoc.AVANetPG2;
    this.AVAPrintReceiptDate    = custTableLoc.AVAPrintReceiptDate  ? custTableLoc.AVAPrintReceiptDate : chainGroupLoc.AVAPrintReceiptDate;
    this.DlvTerm                = custTableLoc.DlvTerm              ? custTableLoc.DlvTerm : chainGroupLoc.AVADlvTerm;
    this.DlvMode                = custTableLoc.DlvMode              ? custTableLoc.DlvMode : chainGroupLoc.AVADlvMode;
    this.Payment                = custTableLoc.PaymTermId           ? custTableLoc.PaymTermId : chainGroupLoc.AVAPayment;
    this.CashDisc               = custTableLoc.CashDisc             ? custTableLoc.CashDisc : chainGroupLoc.AVACashDisc;
    this.KCS_CollComp           = custTableLoc.KCS_CollComp         ? custTableLoc.KCS_CollComp : chainGroupLoc.AVACollComp;
    this.InventSiteId           = custTableLoc.InventSiteId         ? custTableLoc.InventSiteId : AVAWorkerInventSite::find(HcmWorker::findByPerson(DirPersonUser::current().PersonParty).PersonnelNumber).InventSiteId;

    this.AVARackDiscount        = custTableLoc.AVARackDiscount      ? custTableLoc.AVARackDiscount : chainGroupLoc.AVARackDiscount;

    this.KCS_ChainLineDiscCode  = chainGroupLoc.AVALineDisc;

    if(custTableLoc.KCS_MaxBonusAmount > 0
    || chainGroupLoc.AVAMaxBonusAmount > 0)
    {
        this.KCS_DecreaseProf = NoYes::Yes;
    }

    if(custTableLoc.AVAConfirmCentralEmail)
    {
        this.Email              = custTableLoc.AVAConfirmCentralEmail;
    }

    this.avaInitCollectionCommision();

    this.avaUpdateFreightInformation();

    this.avaInitInfoFieldsFromCust();
}

/// <summary>
/// Updates payment and cashDisc fields according to invoiceAccount or its smmBusRelChainGroup
/// </summary>
public void avaUpdateCashDiscPayment()
{
    CustTable custTableLoc;
    smmBusRelChainGroup chainGroupLoc;

    custTableLoc    = this.custTable_InvoiceAccount();
    chainGroupLoc   = smmBusRelChainGroup::avaFindChainId(custTableLoc.CompanyChainId);

    this.Payment                = custTableLoc.PaymTermId           ? custTableLoc.PaymTermId : chainGroupLoc.AVAPayment;
    this.CashDisc               = custTableLoc.CashDisc             ? custTableLoc.CashDisc : chainGroupLoc.AVACashDisc;

}

/// <summary>
///    AVA <c>avaInitCollectionCommision</c> method.
/// </summary>
public void avaInitCollectionCommision()
{
    CustTable           locCustTable;
    smmBusRelChainGroup locSmmBusRelChainGroup;

    locCustTable            = this.custTable_CustAccount();
    locSmmBusRelChainGroup  = smmBusRelChainGroup::avaFindChainId(locCustTable.CompanyChainId);

    if(locCustTable.KCS_CollectionCommisionPerc > 0)
    {
        this.KCS_CollComp   = locCustTable.KCS_CollComp;
    }
    else if(locSmmBusRelChainGroup.AVACollectionCommissionPerc > 0)
    {
        this.KCS_CollComp   = locSmmBusRelChainGroup.AVACollComp;
    }

}

/// <summary>
/// designed by AVANADE
/// </summary>
public void avaInitInfoFieldsFromCust()
{
    KCS_SOCSalesTableInfoFields salesTableInfoFields = KCS_SOCSalesTableInfoFields::find(AVATableInfoFieldTypes::Sales, this.SalesId, true);

    salesTableInfoFields.initInfoFields(this);
}

/// <summary>
///    AVA <c>avaUpdateFreightInformation</c> method.
/// </summary>
public void avaUpdateFreightInformation()
{
    DlvMode locDlvMode;
    DlvTerm locDlvTerm;

    if(this.DlvMode || this.DlvTerm)
    {
        locDlvMode  = DlvMode::find(this.DlvMode);
        locDlvTerm  = DlvTerm::find(this.DlvTerm);

        if(     (locDlvMode.RecId && locDlvMode.KCS_FreightChargeFree)
            ||  (locDlvTerm.RecId && locDlvTerm.KCS_FreightChargeFree)  )
        {
            this.KCS_FreightChargeFree = NoYes::Yes;
        }
        else
        {
            this.KCS_FreightChargeFree = NoYes::No;
        }
    }

    if(locDlvTerm.RecId)
    {
        this.KCS_POC_CarriageFree = locDlvTerm.KCS_POC_CarriageFree;
    }
    else
    {
        this.KCS_POC_CarriageFree = 0.0;
    }

    this.KCS_FreightCalculation = KCS_FreightCalculation::FirstDelivery;
}

/// <summary>
/// designed by AVANADE
/// </summary>
void initFromSmmBusRelChainGroup()
{
    smmBusRelChainGroup     chainGroup;
    select firstonly chainGroup where chainGroup.ChainId == this.KCS_ChainId;
    this.AVARackDiscount = chainGroup.AVARackDiscount;
}

/// <summary>
/// designed by AVANADE
/// </summary>
public void avaUpdateRackDiscount()
{
    SalesLine               salesLine;
    AVASpecialDiscSalesLine specialDiscSL;

    while select salesLine where salesLine.SalesId == this.SalesId
    {
        if (this.avaRackDiscFactorFound(salesLine))
        {
            ttsbegin;
            specialDiscSL = AVASpecialDiscSalesLine::find(salesLine.InventTransId, true);
            specialDiscSL.SpecialDiscountPct7 = this.AVARackDiscount;
            specialDiscSL.update();
            ttscommit;
        }
    }
}

   /// <summary>
   /// designed by AVANADE
   /// </summary>
   public void avaCheckRackDiscount()
   {
       SalesLine               salesLine, salesLineOrig;
       AVASpecialDiscSalesLine specialDiscSL;
       boolean                 mustHaveRackDisc, hasRackDisc, isDelegatedOrder = false;
       SalesId                 salesId = this.SalesId;
       SalesTable              delegatedOrder, origOrder;
       int                     foundItems, ItemsHavingRackDisc;
       RefRecId                salesLineOrigRecId;

       if (this.AVARepPckSlipNum)
       {
           //select count(RecId) from delegatedOrder where delegatedOrder.AVADelegatedToAgent
           select count(RecId) from delegatedOrder where (delegatedOrder.AVADelegatedToAgent  || delegatedOrder.AVADelegatedToAgentIC)
                                                      && delegatedOrder.InventSiteId == this.InventSiteId
                                                      && delegatedOrder.CustAccount == this.CustAccount
                                                      && delegatedOrder.PurchOrderFormNum  == this.PurchOrderFormNum;
           if (!delegatedOrder.RecId)
           {
               throw error("@NDX:NXADelegatedOrderNotFound");
           }
           else if (delegatedOrder.RecId > 1)
           {
               throw error(strFmt("@NDX:NXAMoreThanOneDelegated", this.PurchOrderFormNum));
           }
           else
           {
               select firstonly delegatedOrder where delegatedOrder.AVADelegatedToAgent
                                                      && delegatedOrder.InventSiteId == this.InventSiteId
                                                      && delegatedOrder.CustAccount == this.CustAccount
                                                      && delegatedOrder.PurchOrderFormNum  == this.PurchOrderFormNum;
               salesId = delegatedOrder.SalesId;
               isDelegatedOrder = true;
               origOrder = SalesTable::find(this.SalesId);
               info(strFmt("@NDX:NXARackDiscDelegatedOrder", salesId));
           }
       }

       while select salesLine where salesLine.SalesId == salesId
       {
           hasRackDisc      = false;

           mustHaveRackDisc = this.avaRackDiscFactorFound(salesLine);

           if (!isDelegatedOrder)
           {
               specialDiscSL = AVASpecialDiscSalesLine::find(salesLine.InventTransId);
               if (specialDiscSL.SpecialDiscountPct7)
               {
                   hasRackDisc = true;
               }
           }
           else
           {
               foundItems = 0;
               ItemsHavingRackDisc = 0;
               salesLineOrigRecId = 0;
               if (mustHaveRackDisc)
               {
                   while select salesLineOrig where saleslineorig.SalesId == origOrder.SalesId
                                                 && salesLineOrig.ItemId == salesLine.ItemId
                   {
                       foundItems++;
                       specialDiscSL = AVASpecialDiscSalesLine::find(salesLineOrig.InventTransId);
                       if (specialDiscSL.SpecialDiscountPct7)
                       {
                           ItemsHavingRackDisc++;
                       }
                       else
                       {
                           salesLineOrigRecId = salesLineOrig.RecId;                            
                       }
                   }
                   if (foundItems != ItemsHavingRackDisc)
                   {
                       warning(strFmt("@NDX:NXADelegatedRackDiscAllowed", salesLine.LineNum, salesLine.SalesId, salesLine.ItemId, salesLine.SalesQty));
                       salesLineOrig = SalesLine::findRecId(salesLineOrigRecId);
                       if (this.avaRackDiscFactorFound(salesLineOrig))
                       {
                           warning(strFmt("@NDX:NXARackDiscAllowed", salesLineOrig.LineNum, salesLineOrig.SalesId, salesLineOrig.ItemId, salesLineOrig.SalesQty));
                       }
//                       else
//                       {
//                           warning(strFmt("@NDX:NXADelegatedRackDiscNotAllowed", salesLineOrig.ItemId, salesLineOrig.SalesId));
//                       }
                   }
               }
           }

           if (!isDelegatedOrder)
           {
               if (mustHaveRackDisc && !hasRackDisc)
               {
                   warning(strFmt("@NDX:NXARackDiscAllowed", salesLine.LineNum, salesLine.ItemId, salesLine.SalesQty, salesLine.SalesId));
               }
               if (hasRackDisc && !mustHaveRackDisc)
               {
                   warning(strFmt("@NDX:NXARackDiscNotAllowed", salesLine.LineNum, salesLine.ItemId, salesLine.SalesQty));
               }
           }
       }
   }

private boolean avaRackDiscFactorFound(SalesLine _salesLine)
{
    qty                     rackQty;
    boolean                 ret = false;
    AVARackDiscRules        rackDiscRules;

    rackQty = this.avaGetConversionFactor(_salesLine.SalesUnit, _salesLine.ItemId);
    if (rackQty && (any2Int(_salesLine.SalesQty) mod any2Int(rackQty) == 0))
    {
        ret = true;
    }

    if (!ret)
    {
        select firstonly rackDiscRules where rackDiscRules.ItemId == _salesLine.ItemId;
        rackQty = this.avaGetRackDiscRuleFactor(rackDiscRules.UnitOfMeasureSymbol, _salesLine.SalesUnit, _salesLine.ItemId);
        if (rackQty && (any2Int(_salesLine.SalesQty) mod any2Int(rackQty) == 0))
        {
            ret = true;
        }
    }

    return ret;
}

private Qty avaGetConversionFactor(UnitOfMeasureSymbol _unitOfMeasureSymbol, ItemId _itemId)
{
    EcoResProductRecId      ecoResProduct;
    qty                     rackQty;
    UnitOfMeasure           unitOfMeasure;
    UnitOfMeasureConversion conversion;
    RefRecId                UnitRecId;

    ecoResProduct = InventTable::find(_itemId).Product;
    UnitRecId     = UnitOfMeasure::findBySymbol(_unitOfMeasureSymbol).RecId;
    select firstonly conversion where conversion.Product == ecoResProduct
                                       && conversion.ToUnitOfMeasure == UnitRecId
                join unitOfMeasure where unitOfMeasure.RecId == conversion.FromUnitOfMeasure
                                      && unitOfMeasure.AVARackDiscAble;
    rackQty = conversion.Factor;

    return rackQty;
}

private Qty avaGetRackDiscRuleFactor(UnitOfMeasureSymbol _fromUnitOfMeasureSymbol, UnitOfMeasureSymbol _toUnitOfMeasureSymbol, ItemId _itemId)
{
    EcoResProductRecId      ecoResProduct;
    qty                     rackQty;
    UnitOfMeasureConversion conversion;
    RefRecId                UnitRecIdFrom, UnitRecIdTo;

    ecoResProduct = InventTable::find(_itemId).Product;
    UnitRecIdFrom     = UnitOfMeasure::findBySymbol(_fromUnitOfMeasureSymbol).RecId;
    UnitRecIdTo       = UnitOfMeasure::findBySymbol(_toUnitOfMeasureSymbol).RecId;
    select firstonly conversion where conversion.Product == ecoResProduct
                                       && conversion.FromUnitOfMeasure == UnitRecIdFrom
                                       && conversion.ToUnitOfMeasure == UnitRecIdTo;

    rackQty = conversion.Factor;

    return rackQty;
}

/// <summary>
///    AVA <c>avaUpdateFreightInformationAfterPSPost</c> method.
/// </summary>
/// <param name="_update">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaUpdateFreightInformationAfterPSPost(boolean _update = false)
{
    boolean valuesChanged;

    KCS_FreightCostStatus   origKCS_FreightCostStatus;

    origKCS_FreightCostStatus = this.KCS_FreightCostStatus;

    if(this.KCS_FreightCostStatus == KCS_FreightCostStatus::Empty)
    {
        if(this.KCS_FreightChargeFree == NoYes::No) // freight costs
        {
            if (this.KCS_POC_CarriageFree == 0) //no limit
            {
                this.KCS_FreightCostStatus  = KCS_FreightCostStatus::Required;
            }
            else //limit exists
            {
                if(this.getTotalLineAmount() <= this.KCS_POC_CarriageFree) //below limit
                {
                    this.KCS_FreightCostStatus = KCS_FreightCostStatus::Required;
                }
                else //over limit
                {
                    this.KCS_FreightCostStatus = KCS_FreightCostStatus::None;
                }
            }
        }
        else //no freight cost
        {
            this.KCS_FreightCostStatus = KCS_FreightCostStatus::None;
        }
        valuesChanged = true;
    }
    else if(    this.KCS_FreightCalculation == KCS_FreightCalculation::FirstDelivery
            &&  this.KCS_FreightCosts       != 0)
    {
        if(this.lastPackingSlip() != '')    // if there is an existing packing slip for the sales order, no calculation of freight cost
        {
            if(     this.KCS_FreightChargeFree == NoYes::No
                &&  this.KCS_POC_CarriageFree == 0)
            {
                if(origKCS_FreightCostStatus != KCS_FreightCostStatus::Required)
                {
                    this.KCS_FreightCostStatus  = KCS_FreightCostStatus::Required;
                    valuesChanged = true;
                }
            }

            if(this.KCS_FreightChargeFree == NoYes::Yes)
            {
                if(origKCS_FreightCostStatus != KCS_FreightCostStatus::None)
                {
                    this.KCS_FreightCostStatus  = KCS_FreightCostStatus::None;
                    valuesChanged = true;
                }
            }
            //else if(this.amountOrderedNotInvoiced() <= this.KCS_POC_CarriageFree)
            else if(this.getTotalLineAmount() <= this.KCS_POC_CarriageFree)
            {
                if(origKCS_FreightCostStatus != KCS_FreightCostStatus::Required)
                {
                    this.KCS_FreightCostStatus  = KCS_FreightCostStatus::Required;
                    valuesChanged = true;
                }
            }
            else
            {
                if(origKCS_FreightCostStatus != KCS_FreightCostStatus::None)
                {
                    this.KCS_FreightCostStatus  = KCS_FreightCostStatus::None;
                    valuesChanged = true;
                }
            }
        }
    }

    if(valuesChanged && _update)
    {
        this.selectForUpdate();
        ttsbegin;
        this.update();
        ttscommit;
    }

    return valuesChanged;
}

/// <summary>
///    AVA <c>avaCheckFreightInformationBeforeIPost</c> method.
/// </summary>
/// <param name="_throwWarning">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaCheckFreightInformationBeforeIPost(boolean _throwWarning = true)
{
    boolean retVal;

    retVal = true;

    if(     this.KCS_FreightCostStatus  == KCS_FreightCostStatus::Required
        &&  this.KCS_FreightCosts       == 0                                )
    {
        if(_throwWarning)
        {
            warning(strFmt("@NDX:NXASalesOrderP1FreightCostMissung", this.SalesId));
        }
        retVal = false;
    }

    return retVal;
}

/// <summary>
/// Creates markups for the sales order.
/// </summary>
/// <param name="_deleteExistingMarkupTrans">
/// Determines whether to delete existing markups before creating the new.
/// </param>
/// <param name="_createTieredMarkups">
/// Determines whether to create tiered markups. If this parameter is true then _deleteExistingMarkupTrans will be reset to false.
/// In this case only existing tiered markups will be deleted before creating the new.
/// </param>
public void createMarkupTrans(  boolean _deleteExistingMarkupTrans,
                                boolean _createTieredMarkups)
{
    next createMarkupTrans( _deleteExistingMarkupTrans,
                            _createTieredMarkups        );

    if (this.SkipCreateMarkup == NoYes::No)
    {

        if (this.markupAllowed())
        {
            if(this.avaNeedMarkupForFreightCharge())
            {
                ttsbegin;
                this.avaAddMarkupCollectionCommision();
                ttscommit;
            }
        }
    }
}

