///    <c>boolean</c> as return value
/// </returns>
public boolean avaNeedMarkupForFreightCharge(DlvModeId _DlvModeId = this.DlvMode)
{
    boolean retVal;

    DlvMode locDlvMode;

    retVal      = false;

    locDlvMode  = DlvMode::find(this.DlvMode);
    if(locDlvMode.KCS_ColComActive)
    {
        retVal  = true;
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaCheckMarkupFreightInformationBeforeIPost</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaCheckMarkupFreightInformationBeforeIPost()
{
    boolean retVal;

    AVASalesParameters  locAVASalesParameters;
    MarkupModuleType    locMarkupModuleType;
    MarkupCode          locMarkupCode;
    MarkupTable         locMarkupTable;
    MarkupTrans         locMarkupTransNew;
    MarkupTrans         locMarkupTransSalesTable;

    retVal = false;

    if(     this.KCS_FreightCostStatus  == KCS_FreightCostStatus::Required
        &&  this.KCS_FreightCosts       != 0                                )
    {
        locAVASalesParameters = AVASalesParameters::find();

        if(locAVASalesParameters.RecId)
        {
            locMarkupCode       = locAVASalesParameters.MarkupCodeFreight;
            locMarkupModuleType = MarkupModuleType::Cust;
            locMarkupTable      = MarkupTable::find(locMarkupModuleType, locMarkupCode);
            if(locMarkupTable.RecId)
            {
                locMarkupTransNew.clear();
                locMarkupTransNew.initFromMarkupTable(locMarkupTable);
                locMarkupTransNew.initFromSalesTable(this);
                locMarkupTransNew.Value            = this.KCS_FreightCosts;
                locMarkupTransNew.MarkupCategory   = MarkupCategory::Fixed;
                locMarkupTransNew.Keep             = NoYes::No;

                select firstonly locMarkupTransSalesTable
                where   locMarkupTransSalesTable.TransTableId   == this.TableId
                    &&  locMarkupTransSalesTable.TransRecId     == this.RecId
                    &&  locMarkupTransSalesTable.MarkupCode     == locMarkupTransNew.MarkupCode
                    &&  locMarkupTransSalesTable.TaxItemGroup   == locMarkupTransNew.TaxItemGroup;
                if(!locMarkupTransSalesTable.RecId)
                {
                    locMarkupTransNew.insert();
                }
                retVal = true;
            }
        }
    }
    else
    {
        retVal = true;
    }

    return retVal;
}

/// <summary>
///    AVA <c>avaAddMarkupCollectionCommision</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaAddMarkupCollectionCommision()
{
    boolean retVal;

    CustTable           locCustTable;
    smmBusRelChainGroup locSmmBusRelChainGroup;

    AVASalesParameters  locAVASalesParameters;
    MarkupModuleType    locMarkupModuleType;
    MarkupCode          locMarkupCode;
    MarkupTable         locMarkupTable;
    MarkupTrans         locMarkupTransNew;
    MarkupTrans         locMarkupTransSalesTable;
    boolean             locCreateMarkup;
    DlvModeId           locDlvModeToCheck;

    retVal          = true;
    locCreateMarkup = true;

    locCustTable            = this.custTable_CustAccount();
    locSmmBusRelChainGroup  = smmBusRelChainGroup::avaFindChainId(locCustTable.CompanyChainId);
    locAVASalesParameters   = AVASalesParameters::find();

    if(locAVASalesParameters.RecId)
    {
        locMarkupCode       = locAVASalesParameters.MarkupCodePickUpFee;
        locMarkupModuleType = MarkupModuleType::Cust;
        locMarkupTable      = MarkupTable::find(locMarkupModuleType, locMarkupCode);
        if(locMarkupTable.RecId)
        {
            locMarkupTransNew.clear();
            locMarkupTransNew.initFromMarkupTable(locMarkupTable);
            locMarkupTransNew.initFromSalesTable(this);
            if(locCustTable.KCS_CollectionCommisionPerc > 0)
            {
                locMarkupTransNew.Value            = -locCustTable.KCS_CollectionCommisionPerc;
            }
            else if(locSmmBusRelChainGroup.AVACollectionCommissionPerc > 0)
            {
                locMarkupTransNew.Value            = -locSmmBusRelChainGroup.AVACollectionCommissionPerc;
            }
            else if(    locCustTable.KCS_CollectionCommisionPerc            == 0
                    &&  locSmmBusRelChainGroup.AVACollectionCommissionPerc  == 0    )
            {
                locDlvModeToCheck = DlvMode::avaSalesPickupDlvModeId();
                if(     locDlvModeToCheck
                    &&  this.DlvMode == locDlvModeToCheck   )
                {
                    locCreateMarkup = false;
                }
            }
            locMarkupTransNew.MarkupCategory   = MarkupCategory::Percent;
            locMarkupTransNew.Keep             = NoYes::Yes;

            if(locCreateMarkup)
            {
                select firstonly locMarkupTransSalesTable
                where   locMarkupTransSalesTable.TransTableId   == this.TableId
                    &&  locMarkupTransSalesTable.TransRecId     == this.RecId
                    &&  locMarkupTransSalesTable.MarkupCode     == locMarkupTransNew.MarkupCode
                    &&  locMarkupTransSalesTable.TaxItemGroup   == locMarkupTransNew.TaxItemGroup;
                if(!locMarkupTransSalesTable.RecId)
                {
                    locMarkupTransNew.insert();
                }
            }
        }
        else
        {
            retVal = false;
        }
    }
    else
    {
        retVal = false;
    }
    return retVal;
}

/// <summary>
///    AVA <c>avaRemoveMarkupCollectionCommision</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaRemoveMarkupCollectionCommision()
{
    boolean retVal;

    CustTable           locCustTable;
    smmBusRelChainGroup locSmmBusRelChainGroup;

    AVASalesParameters  locAVASalesParameters;
    MarkupModuleType    locMarkupModuleType;
    MarkupCode          locMarkupCode;
    MarkupTable         locMarkupTable;
    MarkupTrans         locMarkupTransSearch;
    MarkupTrans         locMarkupTransSalesTable;

    retVal = true;

    locCustTable            = this.custTable_CustAccount();
    locSmmBusRelChainGroup  = smmBusRelChainGroup::avaFindChainId(locCustTable.CompanyChainId);
    locAVASalesParameters   = AVASalesParameters::find();

    if(locAVASalesParameters.RecId)
    {
        locMarkupCode       = locAVASalesParameters.MarkupCodePickUpFee;
        locMarkupModuleType = MarkupModuleType::Cust;
        locMarkupTable      = MarkupTable::find(locMarkupModuleType, locMarkupCode);
        if(locMarkupTable.RecId)
        {
            locMarkupTransSearch.clear();
            locMarkupTransSearch.initFromMarkupTable(locMarkupTable);
            locMarkupTransSearch.initFromSalesTable(this);
            locMarkupTransSearch.MarkupCategory   = MarkupCategory::Percent;
            locMarkupTransSearch.Keep             = NoYes::Yes;


            while select  locMarkupTransSalesTable
            where   locMarkupTransSalesTable.TransTableId   == this.TableId
                &&  locMarkupTransSalesTable.TransRecId     == this.RecId
                &&  locMarkupTransSalesTable.MarkupCode     == locMarkupTransSearch.MarkupCode
                &&  locMarkupTransSalesTable.MarkupCategory == locMarkupTransSearch.MarkupCategory
                &&  locMarkupTransSalesTable.Keep           == locMarkupTransSearch.Keep
            {
                ttsbegin;
                locMarkupTransSalesTable.selectForUpdate(true);
                locMarkupTransSalesTable.delete();
                ttscommit;
            }
        }
        else
        {
            retVal = false;
        }
    }
    else
    {
        retVal = false;
    }
    return retVal;
}

/// <summary>
///    AVA <c>avaUpdateFreightInformationAfterIPost</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaUpdateFreightInformationAfterIPost()
{
    boolean             retVal;

    boolean             valuesChanged;
    KCS_FreightCosts    origKCS_FreightCosts;

    MarkupTrans         locMarkupTransSalesTable;

    retVal = true;

    origKCS_FreightCosts = this.KCS_FreightCosts;

    if(     this.KCS_FreightCalculation == KCS_FreightCalculation::FirstDelivery
        &&  this.KCS_FreightCostStatus  != KCS_FreightCostStatus::Calculated)   
    //    && !this.InterCompanyOrder)
    {
        this.KCS_FreightCostStatus = KCS_FreightCostStatus::Calculated;

        valuesChanged = true;
    }
    else if(    this.KCS_FreightCalculation == KCS_FreightCalculation::EachDelivery 
            &&  this.KCS_FreightCosts       != 0)                                   
          // &&  !this.InterCompanyOrder)
    {
        this.KCS_FreightCosts = 0;

        if(origKCS_FreightCosts != this.KCS_FreightCosts)
        {
            valuesChanged = true;
        }
    }

    if(valuesChanged)
    {
        ttsbegin;
        this.selectForUpdate();
        this.update();
        ttscommit;
        retVal = true;
    }

    if(DlvMode::find(this.DlvMode).KCS_ColComActive)
    {
        select firstonly locMarkupTransSalesTable
        where   locMarkupTransSalesTable.TransTableId   == this.TableId
            &&  locMarkupTransSalesTable.TransRecId     == this.RecId
            &&  locMarkupTransSalesTable.MarkupCode     == AVASalesParameters::find().MarkupCodePickUpFee;

        if(!locMarkupTransSalesTable.recid)
        {
            this.avaAddMarkupCollectionCommision();
        }
    }

    return retVal;
}

