/// <summary>
///     AVA <c>AVAFirstPackingSlipNotInvoiced</c> method.
/// </summary>
/// <returns>
///     <c>CustPackingSlipJour</c> as return value
/// </returns>
public CustPackingSlipJour AVAFirstPackingSlipNotInvoiced()
{
    SalesLine           locSalesLine;
    InventTransOrigin   locInventTransOrigin;
    InventTrans         locInventTrans;
    CustPackingSlipJour locCustPackingSlipJour;

    select firstonly locSalesLine
    where   locSalesLine.SalesId == this.SalesId
        join    locInventTransOrigin
        where   locInventTransOrigin.InventTransId      == locSalesLine.InventTransId
            &&  locInventTransOrigin.ReferenceCategory  == InventTransType::Sales
            &&  locInventTransOrigin.ReferenceId        == this.SalesId
            join    locInventTrans
            where   locInventTrans.InventTransOrigin    ==  locInventTransOrigin.RecId
                &&  locInventTrans.PackingSlipId        != ''
                &&  locInventTrans.InvoiceId            == '';

    select firstonly locCustPackingSlipJour
    where   locCustPackingSlipJour.PackingSlipId == locInventTrans.PackingSlipId;

    return locCustPackingSlipJour;
}

/// <summary>
/// Returns the latest CustPackingSlipJour record for the salesTable
/// </summary>
/// <returns>CustPackingSlipJour</returns>
public CustPackingSlipJour avaLastPackinglipRecord()
{
    CustPackingSlipJour locCustPackingSlipJour;
    CustPackingSlipSalesLink locPackingSlipSalesLink;

    select firstonly PackingSlipId, deliveryDate from locPackingSlipSalesLink
        index hint origSalesIdx
        order by DeliveryDate desc, CreatedDateTime desc, PackingSlipId desc // CreatedDateTime is not set on all records
        where locPackingSlipSalesLink.OrigSalesId  == this.SalesId;

    select firstonly locCustPackingSlipJour
        where locCustPackingSlipJour.PackingSlipId == locPackingSlipSalesLink.packingSlipId
            && locCustPackingSlipJour.DeliveryDate == locPackingSlipSalesLink.deliveryDate;

    return locCustPackingSlipJour;
}

