/// <summary>
/// designed by AVANADE
/// </summary>
/// <param name = "_salesId">SalesId</param>
public static void AVAreorgLineNum(SalesId _salesId)
{
    int             LineCounter;
    real            SortLineCounter;
    SalesLine       salesLine;
    List            list;
    ListEnumerator  listEnumerator;

    list            = new List(Types::Int64);
    LineCounter     = 0;
    SortLineCounter = 0.0;

    ttsbegin;

    while select salesLine 
    order by LineNum 
    where   salesLine.SalesId == _salesId
        &&  !salesLine.AVAItemSetComponent
    {
        list.addEnd(salesLine.RecId);
    }

    listEnumerator  = list.getEnumerator();
    while (listEnumerator.moveNext())
    {
        salesLine           = SalesLine::findRecId(listEnumerator.current(), true);
        LineCounter         = LineCounter + 1;
        salesLine.LineNum   = LineCounter;
        salesLine.doUpdate();
        SalesTable::avaReorgLineNumItemSet(salesLine);
    }

    ttscommit;
}

/// <summary>
///    AVA <c>avaReorgLineNumItemSet</c> method.
/// </summary>
/// <param name="_salesLine">
///    <c>SalesLine</c> as type
/// </param>
public static void avaReorgLineNumItemSet(SalesLine _salesLine)
{
    SalesLine   locSalesLine;

    real        locSortSubLineNum;

    locSortSubLineNum = 0.0;

    if(     _salesLine.AVAItemSet 
        &&  _salesLine.avaIsItemSetExpanded()   )
    {
        locSortSubLineNum = 0.0;

        ttsbegin;
        while select forupdate locSalesLine
        order by LineNum
        where locSalesLine.AVAItemSetParent == _salesLine.InventTransId
        {
            locSortSubLineNum       = locSortSubLineNum + 0.001;
            locSalesLine.LineNum    = _salesLine.LineNum + locSortSubLineNum;
            locSalesLine.doUpdate();
        }
        ttscommit;
    }
}

/// <summary>
///    AVA <c>avaCalcKCS_PickingReleaseIndicator</c> method.
/// </summary>
/// <returns>
///    <c>KCS_PickingReleaseIndicator</c> as return value
/// </returns>
public KCS_PickingReleaseIndicator avaCalcKCS_PickingReleaseIndicator()
{
    KCS_PickingReleaseIndicator retVal;

    KCS_PickingReleaseIndicator locKCS_PickingReleaseIndicator;

    SalesTable                  locSalesTable;
    SalesLine                   locSalesLine;

    int                         noOfSalesLinesReleaseForShipment;
    int                         noOfSalesLinesNoReleaseForShipmentWithRemainQty;

    locSalesTable                   = this;

    retVal                          = locSalesTable.KCS_PickingReleaseIndicator;
    locKCS_PickingReleaseIndicator  = locSalesTable.KCS_PickingReleaseIndicator;

    select firstonly locSalesLine
    where   locSalesLine.SalesId                        == this.SalesId
        &&  locSalesLine.KCS_SOCPickingReleaseIndicator == NoYes::Yes;
    if(!locSalesLine.RecId)
    {
        retVal = KCS_PickingReleaseIndicator::NotReleased;
    }
    else
    {
        while select locSalesLine
        where   locSalesLine.SalesId == this.SalesId
        {
            if(locSalesLine.KCS_SOCPickingReleaseIndicator == NoYes::Yes)
            {
                noOfSalesLinesReleaseForShipment++;
            }
            else
            {
                if(locSalesLine.RemainInventPhysical > 0)
                {
                    noOfSalesLinesNoReleaseForShipmentWithRemainQty++;
                }
            }
        }

        if(noOfSalesLinesReleaseForShipment > 0)
        {
            if(noOfSalesLinesNoReleaseForShipmentWithRemainQty == 0)
            {
                retVal = KCS_PickingReleaseIndicator::CompleteReleased;
            }
            else
            {
                retVal = KCS_PickingReleaseIndicator::PartReleased;
            }
        }
    }

    return retVal;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_isEDI">_isEDI</param>
/// <returns>ret</returns>
public boolean AVACheckPODublicate(boolean  _isEDI = false)
{
    boolean         ret = true;
    SalesTable      dublicatedSalesTable2;
    SalesTable      dublicatedSalesTable;
    SalesTable      origin = this.orig();


    if (this.PurchOrderFormNum != '' && this.AVARepPckSlipNum == '')
    {

        this.AVAPOSearchIndex = strRem(this.PurchOrderFormNum,' ') + '#';
        this.AVAPOSearchIndex += this.CustAccount;

        this.AVAPOSearchIndex2 = strRem(this.PurchOrderFormNum,' ') + '#';
        this.AVAPOSearchIndex2 += this.InvoiceAccount;

        select count(RecId) from dublicatedSalesTable2
        where dublicatedSalesTable2.AVAPOSearchIndex2 == this.AVAPOSearchIndex2
            && dublicatedSalesTable2.AVARepPckSlipNum == ''
            && dublicatedSalesTable2.CreatedDateTime <= DateTimeUtil::addYears(DateTimeUtil::getSystemDateTime(),1)
            && dublicatedSalesTable2.RecId            != this.RecId;

        if (dublicatedSalesTable2.RecId > 0)
        {
            select count(RecId) from  dublicatedSalesTable
            where dublicatedSalesTable.AVAPOSearchIndex == this.AVAPOSearchIndex
            && dublicatedSalesTable.CreatedDateTime <= DateTimeUtil::addYears(DateTimeUtil::getSystemDateTime(),1)
            && dublicatedSalesTable.AVARepPckSlipNum == ''
            //&& dublicatedSalesTable.AVADelegatedToAgent == NoYes::No
            && dublicatedSalesTable.RecId            != this.RecId;

            if (dublicatedSalesTable.RecId > 0)
            {
                info(strFmt("@NDX:NXAPODoublicate",this.PurchOrderFormNum,int642Str(dublicatedSalesTable.RecId)));
            }
            else
            {
                info(strFmt("@NDX:NXAPODoublicate2",this.PurchOrderFormNum, int642Str(dublicatedSalesTable2.RecId)));
            }
            this.AVAPurchOrderDublicate = NoYes::Yes;

            ttsbegin;
            dublicatedSalesTable.skipDataMethods(true);
            update_recordset  dublicatedSalesTable
                setting AVAPurchOrderDublicate = NoYes::Yes    
                where dublicatedSalesTable.AVAPOSearchIndex == this.AVAPOSearchIndex
                    && dublicatedSalesTable.CreatedDateTime       <= DateTimeUtil::addYears(DateTimeUtil::getSystemDateTime(),1)
                    && dublicatedSalesTable.RecId           != this.RecId;

            dublicatedSalesTable2.skipDataMethods(true);
            update_recordset  dublicatedSalesTable2
                setting AVAPurchOrderDublicate = NoYes::Yes
                where dublicatedSalesTable2.AVAPOSearchIndex2 == this.AVAPOSearchIndex2
                    && dublicatedSalesTable2.CreatedDateTime       <= DateTimeUtil::addYears(DateTimeUtil::getSystemDateTime(),1)
                    && dublicatedSalesTable2.RecId           != this.RecId;
            ttscommit;
        }
        else
        {
            this.AVAPurchOrderDublicate = NoYes::No;
        }
    }
    if (origin.PurchOrderFormNum != '' || this.AVARepPckSlipNum != '')
    {
        AVAPOSearchIndex        originPOSearchIndex2 = origin.AVAPOSearchIndex2;


        select count(RecId) from dublicatedSalesTable2
        where dublicatedSalesTable2.AVAPOSearchIndex2 == originPOSearchIndex2
            && dublicatedSalesTable2.CreatedDateTime        <= DateTimeUtil::addYears(DateTimeUtil::getSystemDateTime(),1)
            && dublicatedSalesTable2.AVARepPckSlipNum  == ''
            && dublicatedSalesTable2.RecId             != this.RecId;

        if (dublicatedSalesTable2.RecId == 1)
        {
            SalesTable  dublicatedSalesTableUpd;

            ttsbegin;
            dublicatedSalesTableUpd.skipDataMethods(true);
            update_recordset  dublicatedSalesTableUpd
                setting AVAPurchOrderDublicate = NoYes::No
                where dublicatedSalesTableUpd.AVAPOSearchIndex2 == originPOSearchIndex2
                    && dublicatedSalesTableUpd.CreatedDateTime       <= DateTimeUtil::addYears(DateTimeUtil::getSystemDateTime(),1)
                    && dublicatedSalesTableUpd.RecId           != this.RecId;
            ttscommit;
        }
    }
    if (this.PurchOrderFormNum == '' || this.AVARepPckSlipNum != '')
    {
        this.AVAPurchOrderDublicate = NoYes::No;
        this.AVAPOSearchIndex = '';
        this.AVAPOSearchIndex2 = '';
    }

    return ret;
}

