/// <summary>
/// designed from AVA
/// </summary>
/// <returns>boolean</returns>
public boolean AVAValidateTaxGroup()
{
    boolean     ret = true;

    TaxGroupHeading     taxGroupHeading = TaxGroupHeading::find(this.TaxGroup);
    if (!taxGroupHeading.KCS_UseTaxGroupInSales)
    {
        ret = checkFailed(strFmt("@NDX:NXATaxGroupIsNotForSO",this.TaxGroup));
    }

    SalesLine   locSalesLine;

    select firstonly ItemId, RecId from locSalesLine
        where locSalesLine.SalesId == this.SalesId
           && locSalesLine.TaxGroup == '';

    if (locSalesLine.RecId)
    {
        ret = checkFailed(strFmt("@NDX:NXANoTaxGrpInSL", locSalesLine.ItemId));
    }
    select firstonly RecId, ItemId from locSalesLine
        where locSalesLine.SalesId == this.SalesId
           && locSalesLine.TaxGroup != ''
           && locSalesLine.TaxGroup != this.TaxGroup;

    if (locSalesLine.RecId)
    {
        ret = checkFailed(strFmt("@NDX:NXATaxGrpInLineMatchNotSO",locSalesLine.ItemId));
    }

    select firstonly RecId, ItemId from locSalesLine
        where locSalesLine.SalesId == this.SalesId
           && locSalesLine.TaxItemGroup == '';

    if (locSalesLine.RecId)
    {
        ret = checkFailed(strFmt("@NDX:NXANoItemTxGroup",locSalesLine.ItemId));
    }

    if (!this.deliveryAddress().CountryRegionId)
    {
        ret  = checkFailed("@NDX:NXACountryMandForDlv");
    }
    else
    {
        LogisticsAddressCountryRegionId         deliveryCountryRegionId = this.deliveryAddress().CountryRegionId;
        if (taxGroupHeading.KCS_KFBCountryRegionType == CountryRegionType::Domestic && IntrastatCountryRegionParameters::find(deliveryCountryRegionId).CountryRegionType != CountryRegionType::Domestic )
        {
            warning("@NDX:NXAWarningAddAbr");
            warning("@NDX:NXACalcTaxAnyway");
        }
        else
        {
            //Mehrwertsteuergruppe %1 und Land der Lieferadresse %2 passen nicht zusammen
            if (taxGroupHeading.KCS_KFBCountryRegionType != IntrastatCountryRegionParameters::find(deliveryCountryRegionId).CountryRegionType)
            {
                ret   = checkFailed(strFmt("@NDX:NXACountryAndTxGrpError",taxGroupHeading.TaxGroup, deliveryCountryRegionId));
            }

            if (this.VATNum)
            {
                //Die UStId passt nicht zum Land der Lieferadresse
                if (!TaxVATNumTable::find(this.VATNum, deliveryCountryRegionId).RecId)
                {
                    info("@NDX:NXAUstCountryError");
                }
            }

            //Umsatzsteuernummer muss für EU-Lieferungen angegeben werden
            else if (IntrastatCountryRegionParameters::isInEU(deliveryCountryRegionId))
            {
                ret  = checkFailed("@NDX:NXAFailedVATNumError");
            }
            if (!this.OneTimeCustomer && TaxVATNumTable::isVATNumMandatory(CustParameters::find().MandatoryVATNum, this))
            {
                ret   = checkFailed("@NDX:NXAVATMandatoryError");
            }
        }
    }

    return ret;

}

