/// <summary>
/// designed rom AVA
/// </summary>
/// <returns>boolean</returns>
public boolean checkPreferenceAuth()
{
    boolean ok = true;

    if(AVASalesParameters::find().PreferenceAuthorityCheck)
    {
        LogisticsAddressCountryRegionId         deliveryCountryRegionId = this.deliveryAddress().CountryRegionId;
        if (IntrastatCountryRegionParameters::find(deliveryCountryRegionId).AVAPreferenceCheck == NoYes::Yes)
        {
            SalesLine       locSalesLine;
            List            listNotAuthItems = new List(Types::String);
            str             itemsListStr;

            while select ItemId from locSalesLine  
                where locSalesLine.SalesId == this.SalesId
                   && locSalesLine.NDX_PreferenceAuthorized == NDXNoYesBE::No
            {

                listNotAuthItems.addEnd(locSalesLine.ItemId);
            }

            if (!listNotAuthItems.empty())
            {

                ListIterator  listNotAuthItemsIterator = new ListIterator(listNotAuthItems);
                while (listNotAuthItemsIterator.more())
                {
                    if (itemsListStr != '')
                    {
                        itemsListStr += ', ';
                    }
                    itemsListStr += listNotAuthItemsIterator.value();

                    listNotAuthItemsIterator.next();
                }

                warning(strFmt("@NDX:NXAItemsIsNotForPreferDefined",itemsListStr));
            }

            this.avaSetTablePrefAuth();
        }

    }
    return ok;
}

