/// <summary>
///    AVA <c>avaDistributeRedemptionAmount</c> method.
/// </summary>
/// <param name="_amountToDistribute">
///    <c>Amount</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaDistributeRedemptionAmount(Amount _amountToDistribute)
{
    boolean         retVal;

    real            locFactor;
    Amount          locBaseAmount;

    SalesLine       locSalesLine;
    Map             locMap;
    MapEnumerator   locMapEnumerator;

    real            locHK2;

    locMap  = new Map(Types::Record, Types::Real);
    //MapEnumerator   mapEnumerator;

    if(     this.SalesType == SalesType::ReturnItem
        &&  _amountToDistribute                     )
    {
        while select locSalesLine
        where   locSalesLine.SalesId    == this.SalesId
            &&  locSalesLine.LineAmount != 0
        {
            locHK2          = locSalesLine.inventTable().AVAGetHK2perQty(locSalesLine.ExpectedRetQty, locSalesLine.InventDimId);
            locBaseAmount   += abs(locSalesLine.ExpectedRetQty * locHK2);
            locMap.insert(locSalesLine, locHK2);
        }

        if(locBaseAmount)
        {
            ttsbegin;

            locFactor                       = _amountToDistribute / locBaseAmount;
            locMapEnumerator                = locMap.getEnumerator();
            while (locMapEnumerator.moveNext())
            {
                locSalesLine                = locMapEnumerator.currentKey();
                locHK2                      = locMapEnumerator.currentValue();

                locSalesLine.selectForUpdate(true);
                locSalesLine.SalesPrice     = locHK2 * locFactor;
                locSalesLine.LinePercent    = 0;
                locSalesLine.LineDisc       = 0;

                if (locSalesLine.PriceUnit)
                {
                    locSalesLine.SalesPrice = locSalesLine.SalesPrice * locSalesLine.PriceUnit;
                }

                if(locSalesLine.SalesType == SalesType::ReturnItem)
                {
                    locSalesLine.LineAmount = locSalesLine.returnLineAmount(locSalesLine.ExpectedRetQty);
                }
                else
                {
                    locSalesLine.LineAmount = locSalesLine.calcLineAmount(locSalesLine.ExpectedRetQty);
                }
                locSalesLine.update();
            }

            ttscommit;

            retVal  = true;
        }
    }
    return retVal;
}

/// <summary>
/// Extension of method update
/// </summary>
public void update()
{
    if( this.orig().AVAJournalApproval == NoYes::No
        && this.AVAJournalApproval == NoYes::Yes
        && this.WorkerSalesTaker != HcmWorker::userId2Worker(curUserId()))
    {
        this.WorkerSalesTaker = HcmWorker::userId2Worker(curUserId());
    }

    next update();
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesTable_Orig">_salesTable_Orig</param>
protected void updateSalesLinesOnUpdateSalesTable(SalesTable _salesTable_Orig)
{
    next updateSalesLinesOnUpdateSalesTable(_salesTable_Orig);
    if (this.ShippingDateRequested != _salesTable_Orig.ShippingDateRequested
     || this.AVADispoDate          != _salesTable_Orig.AVADispoDate)
    {
        SalesLine       locSalesLine;

        while select locSalesLine
            where locSalesLine.SalesId == this.SalesId
               && locSalesLine.SalesStatus == SalesStatus::Backorder
        {
            if (this.ShippingDateRequested != _salesTable_Orig.ShippingDateRequested)
            {
                locSalesLine.AVAShippingDateRequested = this.ShippingDateRequested;
            }
            if (this.AVADispoDate          != _salesTable_Orig.AVADispoDate)
            {
                locSalesLine.AVADispoDate = this.AVADispoDate;
                locSalesLine.AVADispoDateModifiedDateTime    =  DateTimeUtil::utcNow();
                locSalesLine.AVADispoDateModifiedById        =  curUserId();
            }
            locSalesLine.setCalculatedShippingDate();
            ttsbegin;
            locSalesLine.selectForUpdate(true);
            locSalesLine.doUpdate();
            ttscommit;
        }
    }
}

