/// <summary>
/// ava method
/// </summary>
/// <param name = "lThrowError">boolean</param>
/// <returns>boolean</returns>
public  boolean AVACheckRepPckSlipNum(boolean       lThrowError = true)
{
    SalesTable             salesTable;
    AVASalesParameters     salesParameters = AVASalesParameters::find(false);

    Query                   q;
    QueryRun                qr;
    QueryBuildDataSource    qbds;
    QueryBuildFieldList     qf;
    utcdatetime             l_utcDateTime = DateTimeUtil::utcNow();
    ;
    if (!this.AVARepPckSlipNum)
    {
        return true;
    }

    q       = new Query();
    qbds    = q.addDataSource(tablenum(SalesTable));
    qbds.addRange(fieldnum(SalesTable, InventSiteId)).value(SysQuery::value(this.InventSiteId));
    qbds.addRange(fieldnum(SalesTable, AVARepPckSlipNum)).value(this.AVARepPckSlipNum);
    qbds.addRange(fieldnum(SalesTable, RecId)).value(SysQuery::valueNot(this.RecId));
    qbds.addSortField(fieldnum(salesTable, createdDateTime), SortOrder::Descending);
    qf = qbds.fields();
    qf.addField(fieldnum(SalesTable, SalesId));
    qf.addField(fieldnum(SalesTable, createdDateTime));
    qbds.firstOnly(true);

    // Zeitraumprüfung
    if (salesParameters.RepPckSlipDaysCheck)
    {
        l_utcDateTime = DateTimeUtil::addDays(l_utcDateTime, -salesParameters.RepPckSlipDaysCheck);
        qbds.addRange(fieldnum(SalesTable, createdDateTime)).value(SysQuery::range(l_utcDateTime, DateTimeUtil::utcNow()));
    }
    qr = new QueryRun(q);
    if (qr.next())
    {
        salesTable = qr.get(tablenum(SalesTable));
        if (lThrowError)
        {
            // Der Handelsvertreter-Lieferschein [%1] wurde bereits am [%2] im Auftrag [%3] verwendet. Der Prüfzeitraum für die Eindeutigkeit von Lieferscheinnummern beträgt [%4 Tage]. Der Lieferschein kann nicht erfasst werden.
            Error(strfmt("@NDX:NXAReqNumDaysChackError", this.AVARepPckSlipNum, salesTable.createdDateTime, salesTable.SalesId, salesParameters.RepPckSlipDaysCheck));
        }
        return false;
    }
    return true;
}

/// <summary>
///     AVA <c>avaUpdateJournalSalesStatus</c> method.
///     AVA - Schneider 19.02.2024
/// </summary>
public void avaUpdateAlterJournalSalesStatus()
{
    if(this.SalesType == SalesType::Journal)                // Journal
    {
        if(this.SalesStatus == SalesStatus::BacKOrder)      // Offener Auftrag
        {
            ttsbegin;
            this.selectForUpdate(true);
            this.SalesStatus = SalesStatus::Canceled;       // Storniert
            this.update();
            ttscommit;
        }
        else if(this.SalesStatus == SalesStatus::Canceled)  // Storniert
        {
            ttsbegin;
            this.selectForUpdate(true);
            this.SalesStatus = SalesStatus::BacKOrder;      // Offener Auftrag
            this.update();
            ttscommit;
        }
    }
}

/// <summary>
///     AVA <c>avaDisplayShippingDateConfirmedCommon</c> method.
///     AVA - Schneider 08.03.2024
/// </summary>
/// <returns>
///    <c>AVASalesShippingDateConfirmedCommon</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
public display AVASalesShippingDateConfirmedCommon avaDisplayShippingDateConfirmedCommon()
{
    AVASalesShippingDateConfirmedCommon  retVal;

    SalesLine                           locSalesLine;
    AVASalesShippingDateConfirmedCommon locDateNull;
    boolean                             locFirstTimeChecked;

    locDateNull = dateNull();
    retVal      = locDateNull;

    while select SalesId, ShippingDateConfirmed
    from    locSalesLine
    where   locSalesLine.SalesId                == this.SalesId
        &&  locSalesLine.SalesStatus            == SalesStatus::Backorder
        //&&  locSalesLine.ShippingDateConfirmed  != locDateNull
    {
        if(!locFirstTimeChecked) // one time
        {
            retVal = locSalesLine.ShippingDateConfirmed;
            locFirstTimeChecked = true;
        }

        if(retVal != locSalesLine.ShippingDateConfirmed) // different dates so no further search
        {
            retVal = locDateNull;
            break;
        }
    }

    return retVal;
}

/// <summary>
///     AVA <c>avaUpdateShippingDateConfirmedCommon</c> method.
///     AVA - Schneider 08.03.2024
/// </summary>
/// <param name="_selectForUpdate">
///     <c>boolean</c> as type
/// </param>
public void avaUpdateShippingDateConfirmedCommon(boolean _selectForUpdate = false)
{
    AVASalesShippingDateConfirmedCommon locAVASalesShippingDateConfirmedCommon;

    locAVASalesShippingDateConfirmedCommon = this.avaDisplayShippingDateConfirmedCommon();

    if(     _selectForUpdate
        &&  this.AVAShippingDateConfirmedCommon != locAVASalesShippingDateConfirmedCommon)
    {
        ttsbegin;
        this.selectForUpdate(_selectForUpdate);
        this.AVAShippingDateConfirmedCommon = locAVASalesShippingDateConfirmedCommon;
        this.update();
        ttscommit;
    }
    else
    {
        this.AVAShippingDateConfirmedCommon = locAVASalesShippingDateConfirmedCommon;
    }
}

