/// <summary>
/// AVA/WEN 2024/04/04   AVA_010619_EDIGLNCheck
/// </summary>
/// <returns>boolean</returns>
public boolean avaCheckEDIGLN()
{
    LogisticsPostalAddress  invoiceLogisticsPostalAddress;
    LogisticsLocation       logisticsLocation;

    boolean ret = true;

    if (this.SalesOriginId like '*EDI*')
    {
        invoiceLogisticsPostalAddress = this.custTable_InvoiceAccount().invoiceAddress();
        if (!invoiceLogisticsPostalAddress.RecId)
        {
            ret = checkFailed("@NDX:NXAEDINoInvAddress");
        }
        select firstonly logisticsLocation
                where logisticsLocation.RecId == invoiceLogisticsPostalAddress.Location;
        if (logisticsLocation.AVAEDIGLN == '')
        {
            ret = checkFailed("@NDX:NXANoGLNInInvAddr");
        }
    }
    return ret;

}

/// <summary>
///    AVA <c>avaMarkupTransForPickUpFeeExist</c> method.
///     AVA - Schneider 06.06.2024
/// </summary>
/// <returns>
///    <c>MarkupCode</c> as return value
/// </returns>
public MarkupCode avaMarkupTransForPickUpFeeExist()
{
    MarkupCode  locMarkupCodePickup;
    MarkupTrans locMarkupTrans;

    locMarkupCodePickup = AVASalesParameters::find().MarkupCodePickUpFee;

    if(locMarkupCodePickup)
    {
        select firstonly1 locMarkupTrans
        where   locMarkupTrans.TransTableId == this.TableId
            &&  locMarkupTrans.TransRecId   == this.RecId
            &&  locMarkupTrans.MarkupCode   == locMarkupCodePickup;
        if(locMarkupTrans.RecId == 0)
        {
            locMarkupCodePickup = '';
        }
    }
    return locMarkupCodePickup;
}

/// <summary>
///    AVA <c>avaCheckPickUpFeeChange</c> method.
///     AVA - Schneider 03.06.2024
/// </summary>
/// <param name="_withDialog">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public DialogButton avaCheckPickUpFeeChange(boolean _withDialog = false)
{
    DialogButton    retVal;

    SalesTable      locSalesTableOrig;
    MarkupCode      locMarkupCodePickup;
    MarkupTrans     locMarkupTrans;

    DlvModeId       locDlvModeToCheck;
    DialogButton    locDialogButtonAnswer;
    boolean         locRemoveMarkupTransForPickup;
    str             locBoxText;
    str             locBoxTextTmp;
    str             locBoxTextTmp2;
    LanguageId      locLanguageId;


    retVal = DialogButton::No;

    locMarkupCodePickup = this.avaMarkupTransForPickUpFeeExist();
    if(locMarkupCodePickup != '')
    {
        locDlvModeToCheck = DlvMode::avaSalesPickupDlvModeId();

        locSalesTableOrig = this.orig();

        if(     locSalesTableOrig.DlvMode == locDlvModeToCheck
            &&  this.DlvMode != locSalesTableOrig.DlvMode
            &&  this.DlvMode != '')
        {
            if(_withDialog)
            {
                locLanguageId   = CompanyInfo::find().LanguageId;
                if(this.DlvTerm)
                {
                    locBoxText      = SysLabel::labelId2String(literalStr("@NDX:NXAP1DoNotAllowAnyPickupFee2"), locLanguageId);
                }
                else
                {
                    locBoxText      = SysLabel::labelId2String(literalStr("@NDX:NXAP1DoNotAllowAnyPickupFee"), locLanguageId);
                }

                /* activate if decription is needed
                locBoxTextTmp   = DlvMode::txt(locDlvModeToCheck, locLanguageId);
                if(locBoxTextTmp)
                {
                    locBoxTextTmp = ' - ' + locBoxTextTmp;
                }
                */
                locBoxTextTmp   = SysLabel::labelId2String(literalStr("@SYS210"), locLanguageId) + ' '
                                + this.DlvMode 
                                + locBoxTextTmp;
                if(this.DlvTerm)
                {
                    /* activate if decription is needed
                    locBoxTextTmp2   = DlvTerm::txt(this.DlvTerm, locLanguageId);
                    if(locBoxTextTmp2)
                    {
                        locBoxTextTmp2 = ' - ' + locBoxTextTmp2;
                    }
                    */
                    locBoxTextTmp2  = SysLabel::labelId2String(literalStr("@SYS6576"), locLanguageId) + ' '
                                    + this.DlvTerm
                                    + locBoxTextTmp2;
                    locBoxTextTmp   = locBoxTextTmp + ', ' + locBoxTextTmp2;
                }

                locBoxText      = strfmt(locBoxText, locBoxTextTmp);

                locDialogButtonAnswer = Box::yesNoCancel(   locBoxText,
                                                            DialogButton::Cancel,
                                                            "@SYS28002"             );
                if (locDialogButtonAnswer == DialogButton::Yes)
                {
                    locRemoveMarkupTransForPickup = true;
                }
                else if (locDialogButtonAnswer == DialogButton::No)
                {
                    // ..
                }
                else
                {
                    this.DlvMode    = locSalesTableOrig.DlvMode;
                }
                retVal          = locDialogButtonAnswer;
            }
            else
            {
                locRemoveMarkupTransForPickup = true;
            }
        }

        if(locRemoveMarkupTransForPickup)
        {
            // remove pickups
            ttsbegin;
            while select locMarkupTrans
            where   locMarkupTrans.TransTableId == this.TableId
                &&  locMarkupTrans.TransRecId   == this.RecId
                &&  locMarkupTrans.MarkupCode   == locMarkupCodePickup
            {
                if(locMarkupTrans.recid)
                {
                    locMarkupTrans.selectForUpdate(true);
                    locMarkupTrans.delete();
                }
            }
            ttscommit;
        }
    }
    return retVal;
}

/// <summary>
///     AVA <c>avaSetOrDoUpdateQuotationIdAfterImport</c> method.
///     AVA - Schneider 22.07.2024
/// </summary>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public boolean avaSetOrDoUpdateQuotationIdAfterImport()
{
    boolean             retVal;

    AVASalesParameters  locAVASalesParameters;
    boolean             locValuesCanBeChanged;

    SalesLine           locSalesLine;
    boolean             locSalesLineStatus;

    retVal = true;

    locAVASalesParameters = AVASalesParameters::find();
    //if(locAVASalesParameters.EnableBlockedCustomer)
    if (SysUserInfo::find(curUserId()).AVADataImportUser)
    {
        locValuesCanBeChanged = true;
    }
    if(locValuesCanBeChanged)
    {
        while select locSalesLine
        where locSalesLine.SalesId == this.SalesId
        {
            locSalesLineStatus = locSalesLine.avaSetOrDoUpdateQuotationIdAfterImport(true);
            if(!locSalesLineStatus)
            {
                retVal = locSalesLineStatus;
            }
        }
    }
    else
    {
        retVal = false;
    }

    return retVal;
}

/// <summary>
/// N.Freidenberger 21.01.2025
/// </summary>
/// <returns>boolean</returns>
public boolean AVAcheckQuotationStatus()
{
    boolean ret = true;
    SalesLine   salesLine;

    select firstonly RecId from salesLine
        where salesLine.SalesId == this.SalesId
           && salesLine.AVAEDIQuotationStatus == AVAEDIQuotationStatus::Error;

    if (salesLine.RecId)
    {
        ret = false;
    }

    return ret;
}

/// <summary>
/// AVA/WEN/2025/05/12     AVA_013179_ICDlvDate
/// </summary>
public void AVAupdateDlvDatesForICUpdate()
{ 
    SalesLine salesLine;

    while select forupdate salesline where salesLine.SalesId == this.salesId
    {
        ttsbegin;
        if (salesLine.ShippingDateConfirmed)
        {
            salesLine.ShippingDateConfirmed = max(salesLine.ShippingDateConfirmed, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
            salesLine.ReceiptDateConfirmed = max(salesLine.ShippingDateConfirmed, salesLine.ReceiptDateConfirmed);
            //salesLine.update();
        }
        //else
        //{
        salesLine.ShippingDateRequested = max(salesLine.ShippingDateRequested, DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()));
        if (salesLine.ReceiptDateRequested < salesLine.ShippingDateRequested)
        {
            salesLine.ReceiptDateRequested = salesLine.ShippingDateRequested;
        }
        salesLine.update();
        //}
        ttscommit;
    }
}

