}

/// <summary>
/// AVA/WEN/2025/05/12     AVA_013179_ICDlvDate
/// </summary>
public void AVAinterCompanyAutoCreateOrders()
{
    boolean     interCompanyVendorFound;

    if (this.AVAcanInterCompanyAutoCreateOrders())
    {
        SalesLine   salesLineLocal;

        while select forceplaceholders salesLineLocal
                where salesLineLocal.SalesId     == this.SalesId
                &&    salesLineLocal.InventRefId == ''
                &&    salesLineLocal.ItemId      != ''
        {
            if (salesLineLocal.defaultIntercompanyVendor().interCompanyTradingRelationActive())
            {
                interCompanyVendorFound = true;
                break;
            }
        }

        // Don't execute intercompany logic for exchange orders - intercompany processing
        // will happen when the exchange is completed via the
        // returns process or payments are approved or when the last hold
        // is released against it.
        if (interCompanyVendorFound
            && (!this.mcrIsCallCenter() || !this.mcrReturnSalesTable().IsExchange))
        {
            TradeInterCompany::autoCreateOrder(this);
        }
    }
}

/// <summary>
/// NDX Check if the colo of an item ist set correctly
/// </summary>
/// <returns>boolean</returns>
public boolean checkLineColor()
{
    boolean     ok = true;
    SalesLine   locSalesLine;

    while select  locSalesLine
        where locSalesLine.SalesId == this.SalesId
    {
        locSalesLine.ndxValidateColor(true);
    }

    return ok;
}
